"use strict";

const https = require("https");

const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

const WEB_CLIENT_ID = "kimne78kx3ncx6brgo4mv6wki5h1ko";
const GQL_URL = "https://gql.twitch.tv/gql";
const GQL_HOST = "gql.twitch.tv";
const GQL_PATH = "/gql";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function gqlViaHttps(body) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify(body);
    const req = https.request(
      {
        hostname: GQL_HOST,
        path: GQL_PATH,
        method: "POST",
        timeout: 20000,
        headers: {
          "user-agent": UA,
          "content-type": "application/json",
          "client-id": WEB_CLIENT_ID,
          origin: "https://www.twitch.tv",
          referer: "https://www.twitch.tv/",
          "content-length": Buffer.byteLength(payload),
        },
      },
      (res) => {
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", () => {
          const text = Buffer.concat(chunks).toString("utf8");
          if (!res.statusCode || res.statusCode < 200 || res.statusCode >= 300) {
            reject(
              new Error(`Twitch data endpoint answered HTTP ${res.statusCode}`)
            );
            return;
          }
          try {
            resolve(JSON.parse(text));
          } catch {
            reject(new Error("Twitch data endpoint returned unreadable JSON"));
          }
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("Twitch data endpoint timed out")));
    req.on("error", reject);
    req.write(payload);
    req.end();
  });
}

async function gqlOnce(body) {
  if (typeof fetch === "function") {
    const ctl = new AbortController();
    const to = setTimeout(() => ctl.abort(), 20000);
    try {
      const res = await fetch(GQL_URL, {
        method: "POST",
        headers: {
          "user-agent": UA,
          "content-type": "application/json",
          "client-id": WEB_CLIENT_ID,
          origin: "https://www.twitch.tv",
          referer: "https://www.twitch.tv/",
        },
        body: JSON.stringify(body),
        signal: ctl.signal,
      });
      if (!res.ok)
        throw new Error(`Twitch data endpoint answered HTTP ${res.status}`);
      return await res.json();
    } finally {
      clearTimeout(to);
    }
  }
  return gqlViaHttps(body);
}

async function gql(body, attempts = 3) {
  let lastErr = null;
  for (let i = 0; i < attempts; i++) {
    try {
      return await gqlOnce(body);
    } catch (err) {
      lastErr = err;
      await sleep(700 * (i + 1));
    }
  }
  throw lastErr || new Error("Twitch data endpoint did not respond");
}

function parseClipSlug(input) {
  const s = String(input || "").trim();
  let m = s.match(/twitch\.tv\/[^/?#]+\/clip\/([A-Za-z0-9_-]+)/i);
  if (m) return m[1];
  m = s.match(/clips\.twitch\.tv\/embed\?[^#]*clip=([A-Za-z0-9_-]+)/i);
  if (m) return m[1];
  m = s.match(/clips\.twitch\.tv\/([A-Za-z0-9_-]+)/i);
  if (m) return m[1];
  if (/^[A-Za-z0-9_-]{10,80}$/.test(s) && !/^\d+$/.test(s)) return s;
  return null;
}

function parseVideoId(input) {
  const s = String(input || "").trim();
  const m = s.match(/twitch\.tv\/videos\/(\d{5,20})/i);
  if (m) return m[1];
  if (/^\d{5,20}$/.test(s)) return s;
  return null;
}

function isVideoInput(input) {
  return (
    /twitch\.tv\/videos\/\d/i.test(String(input || "")) ||
    /^\d{5,20}$/.test(String(input || "").trim())
  );
}

function signUrl(sourceURL, token) {
  if (!sourceURL || !token || !token.signature || !token.value)
    return sourceURL || null;
  const sep = sourceURL.includes("?") ? "&" : "?";
  return `${sourceURL}${sep}sig=${token.signature}&token=${encodeURIComponent(
    token.value
  )}`;
}

function legacyMp4FromThumbnail(thumbnailURL) {
  if (!thumbnailURL) return null;
  const m = thumbnailURL.match(
    /clips-media-assets2\.twitch\.tv\/([A-Za-z0-9_-]+?)(?:-preview-|\.jpg|\.png)/i
  );
  if (!m) return null;
  return `https://clips-media-assets2.twitch.tv/${m[1]}.mp4`;
}

function qualityLabel(raw) {
  if (raw === null || raw === undefined || raw === "") return null;
  const s = String(raw);
  if (/^\d+$/.test(s)) return `${s}p`;
  if (/^\d+p$/i.test(s)) return s;
  return s;
}

function shapeClip(clip, slug) {
  const token = clip.playbackAccessToken || null;
  const qualities = (clip.videoQualities || [])
    .filter((q) => q && q.sourceURL)
    .map((q) => ({
      quality: q.quality || null,
      frameRate: typeof q.frameRate === "number" ? q.frameRate : null,
      url: signUrl(q.sourceURL, token),
    }))
    .sort(
      (a, b) => (parseInt(b.quality, 10) || 0) - (parseInt(a.quality, 10) || 0)
    );

  let downloadUrl = qualities.length ? qualities[0].url : null;
  let bestQuality = qualities.length ? qualities[0].quality : null;
  let legacy = false;
  if (!downloadUrl) {
    downloadUrl = legacyMp4FromThumbnail(clip.thumbnailURL);
    bestQuality = null;
    legacy = !!downloadUrl;
  }

  const broadcaster = clip.broadcaster || {};
  return {
    title: clip.title || clip.slug || slug || "Twitch Clip",
    uploader: broadcaster.displayName || broadcaster.login || null,
    duration:
      typeof clip.durationSeconds === "number" ? clip.durationSeconds : null,
    thumbnail: clip.thumbnailURL || null,
    downloadUrl,
    quality: qualityLabel(bestQuality),
    legacy,
  };
}

const CLIP_QUERY = `query($slug: ID!) {
  clip(slug: $slug) {
    id slug title viewCount durationSeconds createdAt language thumbnailURL
    broadcaster { displayName login profileImageURL(width: 70) }
    curator { displayName login }
    game { name displayName }
    videoQualities { frameRate quality sourceURL }
    playbackAccessToken(params: {platform: "web", playerBackend: "mediaplayer", playerType: "site"}) { signature value }
  }
}`;

module.exports = async function fetchSelf(url) {
  try {
    if (isVideoInput(url)) {
      throw new Error(
        "Twitch VOD URLs are not supported by this source (VOD playback is HLS-only, no direct MP4)"
      );
    }
    if (parseVideoId(url) && !parseClipSlug(url)) {
      throw new Error(
        "Twitch VOD URLs are not supported by this source (VOD playback is HLS-only, no direct MP4)"
      );
    }

    const slug = parseClipSlug(url);
    if (!slug) throw new Error("Invalid Twitch clip URL");

    const json = await gql({ query: CLIP_QUERY, variables: { slug } });
    if (json.errors && json.errors.length && !json.data) {
      throw new Error(`Twitch refused the clip lookup: ${json.errors[0].message}`);
    }
    const clip = json.data && json.data.clip;
    if (!clip) {
      throw new Error(
        "Could not extract this clip — it may be deleted, or Twitch changed its data format"
      );
    }

    const shaped = shapeClip(clip, slug);
    if (!shaped.downloadUrl) {
      throw new Error("This clip exposes no downloadable MP4");
    }

    return {
      success: true,
      source: "Twitch",
      data: {
        title: shaped.title,
        uploader: shaped.uploader,
        duration: shaped.duration,
        thumbnail: shaped.thumbnail,
        download: {
          video: shaped.downloadUrl,
          type: "mp4",
          quality: shaped.quality,
          note: shaped.legacy
            ? "Legacy thumbnail-derived MP4 URL; rendition quality is not exposed for this clip"
            : "Direct self-scrape via anonymous Twitch GraphQL; signed URL for the best available rendition (signatures expire, resolve fresh)",
        },
      },
    };
  } catch (e) {
    if (/^Twitch Error:/.test(e.message)) throw e;
    throw new Error("Twitch Error: " + e.message);
  }
};
